// src/FeaturePage.jsx
import React, { useState, useEffect } from 'react';
import './style/FeaturePage.css';

const MODELS_STORAGE_KEY = 'titanicAppManagedModels';

// List of available features for model training.
// These correspond to the data keys the backend expects.
const availableFeatures = [
  'Title', 'Pclass', 'Sex', 'Age', 'Fare', 'IsAlone', 'Embarked', 'AgeClass'
];

// Default models available to logged-in users
const defaultLoggedInModels = [
  "Random Forest", 
  "SVM", 
  "Logistic Regression", 
  "KNN", 
  "Decision Tree"
];

/**
 * Retrieves the list of models from localStorage.
 * Initializes with defaults if none are found.
 */
const getStoredModels = () => {
  try {
    const modelsJson = localStorage.getItem(MODELS_STORAGE_KEY);
    if (modelsJson) {
      const parsedModels = JSON.parse(modelsJson);
      return Array.isArray(parsedModels) ? parsedModels : [...defaultLoggedInModels];
    } else {
      localStorage.setItem(MODELS_STORAGE_KEY, JSON.stringify(defaultLoggedInModels));
      return [...defaultLoggedInModels];
    }
  } catch (error) {
    console.error("Error parsing models from localStorage:", error);
    localStorage.setItem(MODELS_STORAGE_KEY, JSON.stringify(defaultLoggedInModels));
    return [...defaultLoggedInModels];
  }
};

/**
 * Stores the given list of models into localStorage.
 * @param {string[]} models - An array of model names to store.
 */
const storeModels = (models) => {
  try {
    localStorage.setItem(MODELS_STORAGE_KEY, JSON.stringify(models));
  } catch (error) {
    console.error("Error saving models to localStorage:", error);
  }
};


/**
 * FeaturePage Component (Admin Only)
 * - Allows an admin to delete existing models.
 * - Allows an admin to "train" a new model by selecting features and providing a name.
 */
function FeaturePage() {
  const [models, setModels] = useState([]);
  const [newModelName, setNewModelName] = useState('');
  const [selectedFeatures, setSelectedFeatures] = useState([]);
  const [isTraining, setIsTraining] = useState(false);
  const [feedbackMessage, setFeedbackMessage] = useState({ type: '', text: '' });

  // Load models from storage when component mounts
  useEffect(() => {
    setModels(getStoredModels());
  }, []);

  /**
   * Handles toggling a feature checkbox.
   * @param {string} featureName - The feature to add or remove.
   */
  const handleFeatureToggle = (featureName) => {
    setSelectedFeatures(prev =>
      prev.includes(featureName)
        ? prev.filter(f => f !== featureName)
        : [...prev, featureName]
    );
  };

  /**
   * Simulates a backend API call to train a model.
   * In a real app, this would be a fetch request.
   * @param {string} modelName - The name for the new model.
   * @param {string[]} features - The list of features to train on.
   * @returns {Promise<{success: boolean, message: string}>}
   */
  const simulateTrainingApiCall = (modelName, features) => {
    console.log(`Simulating training for model "${modelName}" with features:`, features);
    return new Promise((resolve) => {
      // Simulate network delay
      setTimeout(() => {
        resolve({ success: true, message: `Model "${modelName}" trained successfully.` });
      }, 1500); // 1.5 second delay
    });
  };

  /**
   * Handles the submission of the new model training form.
   */
  const handleTrainModel = async (e) => {
    e.preventDefault();
    setFeedbackMessage({ type: '', text: '' });

    // --- Validation ---
    if (!newModelName.trim()) {
      setFeedbackMessage({ type: 'error', text: 'Model name cannot be empty.' });
      return;
    }
    if (models.some(m => m.toLowerCase() === newModelName.trim().toLowerCase())) {
      setFeedbackMessage({ type: 'error', text: 'A model with this name already exists.' });
      return;
    }
    if (selectedFeatures.length < 2) {
      setFeedbackMessage({ type: 'error', text: 'Please select at least two features to train the model.' });
      return;
    }

    setIsTraining(true);

    const result = await simulateTrainingApiCall(newModelName.trim(), selectedFeatures);

    setIsTraining(false);

    if (result.success) {
      const updatedModels = [...models, newModelName.trim()];
      storeModels(updatedModels);
      setModels(updatedModels);
      setFeedbackMessage({ type: 'success', text: result.message });
      // Reset form
      setNewModelName('');
      setSelectedFeatures([]);
    } else {
      setFeedbackMessage({ type: 'error', text: result.message || "An unknown error occurred during training." });
    }
  };

  /**
   * Handles deleting an existing model.
   */
  const handleDeleteModel = (modelNameToDelete) => {
    if (window.confirm(`Are you sure you want to delete the model: "${modelNameToDelete}"?`)) {
      const updatedModels = models.filter(model => model !== modelNameToDelete);
      storeModels(updatedModels);
      setModels(updatedModels);
      setFeedbackMessage({ type: 'success', text: `Model "${modelNameToDelete}" has been deleted.` });
    }
  };

  /**
   * Resets the models list to the default set.
   */
  const handleResetModels = () => {
    if (window.confirm("Are you sure you want to reset all models to their default set?")) {
      storeModels(defaultLoggedInModels);
      setModels(defaultLoggedInModels);
      setFeedbackMessage({ type: 'success', text: "Models have been reset to the default set." });
    }
  };

  return (
    <div className="feature-page-container">
      <h1>Model Management (Admin)</h1>
      <p>Manage models available to users in the calculator. Changes take effect immediately.</p>

      {/* --- Section for Training a New Model --- */}
      <div className="training-section">
        <h2>Train a New Model</h2>
        <form onSubmit={handleTrainModel} noValidate>
          <div className="form-group-textfield">
            <label htmlFor="modelName">New Model Name</label>
            <input
              type="text"
              id="modelName"
              value={newModelName}
              onChange={(e) => setNewModelName(e.target.value)}
              placeholder="e.g., My Custom Model"
              disabled={isTraining}
            />
          </div>

          <div className="form-group-features">
            <label>Select Features for Training</label>
            <div className="features-checkbox-group">
              {availableFeatures.map(feature => (
                <div key={feature} className="checkbox-item">
                  <input
                    type="checkbox"
                    id={`feature-${feature}`}
                    checked={selectedFeatures.includes(feature)}
                    onChange={() => handleFeatureToggle(feature)}
                    disabled={isTraining}
                  />
                  <label htmlFor={`feature-${feature}`}>{feature}</label>
                </div>
              ))}
            </div>
          </div>
          
          <button type="submit" className="train-btn" disabled={isTraining}>
            {isTraining ? 'Training...' : 'Train Model'}
          </button>
        </form>
        {feedbackMessage.text && (
          <div className={`feedback-message ${feedbackMessage.type}`}>
            {feedbackMessage.text}
          </div>
        )}
      </div>

      <hr className="section-divider" />

      {/* --- Section for Managing Existing Models --- */}
      <div className="management-section">
        <h2>Existing Models</h2>
        {models.length > 0 ? (
          <ul className="models-list">
            {models.map((modelName) => (
              <li key={modelName} className="model-item">
                <span>{modelName}</span>
                <button
                  onClick={() => handleDeleteModel(modelName)}
                  className="delete-btn"
                  aria-label={`Delete ${modelName} model`}
                  disabled={isTraining}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        ) : (
          <p>No models are currently configured.</p>
        )}
        <button
          onClick={handleResetModels}
          className="reset-models-btn"
          disabled={isTraining}
        >
          Reset to Default Models
        </button>
      </div>
    </div>
  );
}

export default FeaturePage;
